/**
 * THE REFERENCE RIG
 * ----------------------------------------------------------------------------
 * Every number on this site is generated by a deterministic model that is
 * calibrated to ONE specific machine — the laptop this site was written on:
 *
 *   CPU  AMD Ryzen 9 8940HX   (Zen 4 "Dragon Range", 16C/32T, 5.3 GHz boost)
 *   GPU  NVIDIA GeForce RTX 5060 Laptop 8 GB GDDR7 (Blackwell GB206, PCIe 5.0 x8)
 *
 * Nothing here is measured at runtime. These are published / typical figures
 * used as model constants, so the site behaves identically on every visitor's
 * machine and when it is hosted on the web.
 */

export interface RigCpu {
  name: string;
  codename: string;
  arch: string;
  cores: number;
  threads: number;
  baseGhz: number;
  boostGhz: number;
  l1dKb: number;
  l2Mb: number;
  l3Mb: number;
  smt: boolean;
  avx512: boolean;
  fmaWidthBits: number; // AVX-512 = 512-bit = 16 fp32 lanes
  memType: string;
  memGbs: number;
  tdpW: string;
}

export interface RigGpu {
  name: string;
  codename: string;
  arch: string;
  smCount: number;
  cudaCores: number;
  coresPerSm: number;
  warpsPerSm: number; // 48 warps / 1536 threads per SM on Blackwell
  threadsPerSm: number;
  warpSize: number;
  boostGhz: number;
  vramGb: number;
  vramType: string;
  busBits: number;
  vramGbs: number;
  l2Mb: number;
  sharedMemKb: number; // per SM
  sharedBanks: number;
  pcieGen: number;
  pcieLanes: number;
  pcieGbs: number; // theoretical one-directional
  fp32Tflops: number;
  tensorCores: number;
  rtCores: number;
  tgpW: string;
}

export interface RigMemory {
  lineBytes: number;
  pageKb: number;
  dramLatencyCycles: number;
  vramLatencyCycles: number;
  pcieLatencyUs: number;
  streamingWidthGb: number; // pinned / DMA effective one-way
}

