/** Small headline figures reused across the landing page. */
export const RIG_HEADLINE = {
  cpuCores: RIG_CPU.cores,
  cpuThreads: RIG_CPU.threads,
  cpuBoost: `${RIG_CPU.boostGhz} GHz`,
  cpuL3: `${RIG_CPU.l3Mb} MB`,
  gpuCuda: RIG_GPU.cudaCores.toLocaleString('en-US'),
  gpuSm: RIG_GPU.smCount,
  gpuVram: `${RIG_GPU.vramGb} GB`,
  gpuBandwidth: `${RIG_GPU.vramGbs} GB/s`,
  pcie: `PCIe ${RIG_GPU.pcieGen}.0 ×${RIG_GPU.pcieLanes}`,
  bandwidthRatio: (RIG_GPU.vramGbs / RIG_CPU.memGbs).toFixed(1), // ≈4.6×
  laneRatio: Math.round(RIG_GPU.cudaCores / RIG_CPU.threads), // ≈104×
};

/** Derived constants the generators use. Keep all model maths flowing from here. */
export const MODEL = {
  cpuClockGhz: RIG_CPU.boostGhz,
  gpuClockGhz: RIG_GPU.boostGhz,
  /** Cycle costs used by the generators (typical Zen 4 + Blackwell figures). */
  l1Cycles: 4,
  l2Cycles: 14,
  l3Cycles: 46,
  dramCycles: RIG_MEMORY.dramLatencyCycles,
  vramCycles: RIG_MEMORY.vramLatencyCycles,
  sharedCycles: 22,
  bankConflictStall: 18,
  registerCycles: 1,
  /** Throughput ratios that drive the CPU-vs-GPU experiments. */
  gpuWidthVsCpuLane: 1, // both modelled per-lane in the kitchen view
  avx512Lanes: 16,
};
